import numpy as np
from dotmap import DotMap

def add_batch(batch) -> torch.Tensor:
    """
    This function recursively adds a new dimension to the input data structure (which can be a batch of data in various formats such as tuple, list, dictionary, torch.Tensor, or numpy.ndarray) at the zeroth position. It is designed to handle nested data structures by applying the same operation to each element.

    Input-Output Arguments
    :param batch: Union[tuple, list, dict, torch.Tensor, np.ndarray]. The input data which can be a single item or a batch of items in various formats. The function processes this data by adding a new dimension to it or its elements.
    :return: Union[torch.Tensor, np.ndarray]. The modified batch with an added dimension at the zeroth position. This return type ensures compatibility with PyTorch and NumPy data structures.
    """

    # Base case: if the input is a torch.Tensor or np.ndarray, return it as is
    if isinstance(batch, (torch.Tensor, np.ndarray)):
        return batch.unsqueeze(0)

    # Base case: if the input is a single item (like an integer or a string), return it as is
    if isinstance(batch, (int, float, str, bool)):
        return torch.tensor(batch).unsqueeze(0)

    # Recursive case: if the input is a tuple or list, recursively apply the `add_batch` function to each element
    if isinstance(batch, (tuple, list)):
        batch = [add_batch(b) for b in batch]

    # Recursive case: if the input is a dictionary, create a new `dotdict` and recursively apply `add_batch` to each value
    if isinstance(batch, dict):
        batch = DotMap({k: add_batch(v) for k, v in batch.items()})

    # Convert the result to a torch.Tensor or np.ndarray
    if isinstance(batch, list):
        batch = torch.tensor(batch)
    elif isinstance(batch, tuple):
        batch = torch.tensor(list(batch))
    elif isinstance(batch, dict):
        batch = torch.tensor([v for v in batch.values()])

    return batch
