def generate_safe_fn(fn, gradient_fn, input_range):
    @custom_jvp
    def safe_fn(x):
        clipped_x = jnp.clip(x, *input_range)
        return fn(clipped_x)

    @safe_fn.defjvp
    def safe_fn_jvp(primals, tangents):
        x, = primals
        x_dot, = tangents
        clipped_x = jnp.clip(x, *input_range)
        clipped_x_dot = jnp.clip(x_dot, *input_range)
        return (fn(clipped_x), gradient_fn(clipped_x, clipped_x_dot, clipped_x_dot))

    return safe_fn

def safe_exp(max_val):
    min_val = -np.log(max_val)
